def cells_covered_at_least(rows, cols, rects, m):
    seen = [[0] * cols for _ in range(rows)]
    for r1, c1, r2, c2 in rects:
        for r in range(r1, r2 + 1):
            line = seen[r]
            for c in range(c1, c2 + 1):
                line[c] += 1
    return sum(1 for line in seen for v in line if v >= m)
